import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {Database} from 'bun:sqlite';
import {indexPathFor,INDEX_DIR,HOME} from '../../../src/engine';
import {baseStamp,openLive} from '../../../src/delta';
import {initDirectoryRetries,queueDirectory,recoverDirectory,seedScanDirectories} from '../../../src/targeted-rescan';
import {searchIndexPath} from '../../../src/path-search';
const index='demo',root=path.join(HOME,'Library','CloudStorage','fixture'),folder=path.join(root,'offline'),directory=path.join(folder,'child');
fs.mkdirSync(INDEX_DIR,{recursive:true});fs.mkdirSync(directory,{recursive:true});fs.writeFileSync(indexPathFor(index),'');
const scope={name:index,paths:[path.dirname(root)],options:{includeIgnored:true,includeHidden:true},exclusions:['excluded'],configurationChanged:false} as any;
const stamp=baseStamp(index);let db=openLive();initDirectoryRetries(db);db.query('INSERT INTO scopes(name,stamp,revision,problem) VALUES (?,?,?,?)').run(index,stamp,1,'global gap');
const prep=new Database(searchIndexPath(index),{create:true});
prep.exec('CREATE TABLE meta(key PRIMARY KEY,value);CREATE TABLE directories(id INTEGER PRIMARY KEY,path TEXT UNIQUE);CREATE TABLE files(parent INTEGER,name TEXT,dir INTEGER,slash INTEGER,UNIQUE(parent,name))');
prep.query("INSERT INTO meta VALUES ('source',?),('ready','1'),('liveRevision','1')").run(stamp);
prep.query('INSERT INTO directories VALUES (1,?),(2,?),(3,?)').run(root+'/',folder+'/',directory+'/');
prep.exec("INSERT INTO files VALUES(1,'offline',1,1),(2,'child',1,1),(2,'stale',0,0),(3,'existing',0,0)");
fs.writeFileSync(path.join(directory,'existing'),'test');
const seed=()=>db.transaction(()=>seedScanDirectories(db,scope,stamp,'scan',[folder,folder,path.join(folder,'excluded'),'/private/invalid']))();
assert.equal(seed(),1);
const get=()=>db.query('SELECT * FROM directory_retries WHERE path=?').get(folder);
const revision=()=>db.query("SELECT revision FROM scopes WHERE name='demo'").get().revision;
await recoverDirectory(db,scope,async()=>{throw Error('EIO reading provider directory')},1000);
assert.equal(revision(),1);assert.equal(get().retryAt,31000);assert.equal(get().attempts,1);
const nextOffline=path.join(root,'other-offline'),healthy=path.join(path.dirname(root),'healthy','online');
queueDirectory(db,scope,nextOffline,stamp,'event');fs.mkdirSync(healthy,{recursive:true});queueDirectory(db,scope,healthy,stamp,'event');
const attempted:string[]=[];
await recoverDirectory(db,scope,async p=>{attempted.push(p);return {paths:[],directories:new Set<string>(),kind:'directory'}},1001);
assert.deepEqual(attempted,[healthy]);assert.equal(await recoverDirectory(db,scope,async()=>{throw Error('must not retry unreachable provider')},1002),false);
db.query('DELETE FROM directory_retries WHERE path=?').run(nextOffline);
const clock=revision();
db.close();db=openLive();initDirectoryRetries(db);assert.equal(seed(),0);assert.equal(get().retryAt,31000);
await recoverDirectory(db,scope,async()=>{db.query('INSERT INTO changes VALUES (?,?,?,?,?)').run(index,folder+'/raced',1,0,clock+1);db.query("UPDATE scopes SET revision=? WHERE name='demo'").run(clock+1);return {paths:[],directories:new Set<string>(),kind:'directory'};},31001);
assert.equal(revision(),clock+1);assert.equal(get().attempts,2);
fs.writeFileSync(folder+'/added','new');fs.writeFileSync(folder+'/raced','raced');
await recoverDirectory(db,scope,undefined,100000);
const lookup=(p:string)=>db.query("SELECT present,revision FROM changes WHERE scope='demo' AND path=?").get(p);
assert.equal(lookup(folder+'/stale').present,0);assert.equal(lookup(folder+'/added').present,1);
assert.equal(lookup(folder+'/raced').revision,clock+1);assert.equal(get(),null);assert.equal(seed(),0);
const before=revision();await recoverDirectory(db,scope,undefined,100001);assert.equal(revision(),before);
assert.equal(db.query('SELECT count(*) AS n FROM directory_retries').get().n,0);
const many=path.join(root,'many');fs.mkdirSync(many);
for(let i=0;i<600;i++)fs.writeFileSync(many+'/item-'+String(i).padStart(3,'0'),'');
queueDirectory(db,scope,many,stamp,'event');
await recoverDirectory(db,scope,undefined,100002);assert(db.query('SELECT cursor FROM directory_retries WHERE path=?').get(many)?.cursor);
db.close();db=openLive();await recoverDirectory(db,scope,undefined,100003);await recoverDirectory(db,scope,undefined,100004);
assert.equal(db.query('SELECT count(*) AS n FROM changes WHERE path LIKE ?').get(many+'/%').n,600);
assert.equal(db.query('SELECT count(*) AS n FROM directory_retries').get().n,0);
assert.equal(db.query("SELECT problem FROM scopes WHERE name='demo'").get().problem,'global gap');
prep.close();db.close();
